// @generated by:gauntlet run:godseye-local-delivery
import { randomUUID } from "node:crypto";
import { readFile, stat, writeFile } from "node:fs/promises";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import type { ManagedDeliveryProvider } from "../packages/core/src/delivery-managed-provider.js";
import type { DeliveryManifest, DeliveryScope } from "../packages/core/src/delivery-provider.js";
